const category=id=>db.categories.find(c=>c.id===id), taskColor=t=>t.color||category(t.category)?.color||'#e9a8be', pending=()=>db.tasks.filter(t=>!t.done), balance=b=>Number(b.initial||0)+db.transactions.filter(t=>t.bank===b.id).reduce((a,t)=>a+(t.type==='in'?1:-1)*t.amount,0), goalValue=id=>db.transactions.filter(t=>t.project===id).reduce((a,t)=>a+(t.type==='in'?1:-1)*t.amount,0);
